#!ibl edition=2
$root = "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-18_76회차"
$out = f"${$root}/ai/variant"
$base = [self:read]{path:f"${$root}/ai/base/report.json"}
$man = [self:read]{path:f"${$root}/inputs/ai/manifest.json"}
$bids = $base.data.rows >> [table:each]{ return $it.id }
$mids = $man.data.rows >> [table:each]{ return $it.id }
assert $bids == $mids, "명부와 직전 결과의 행 불일치", {base:$bids,manifest:$mids}
[def:대조]($b) {
  $f = [try]{ return [self:forage]{op:"recall",locus:$b.path,evidence_check:"content"} }[catch]{ return null }
  $mine = $f == null ? [] : ($f.map >> [table:filter]{where:($r)=>$r.id == $b.note_id})
  $hit = len($mine) == 1 ? $mine[0] : null
  $es = $hit == null ? null : $hit.evidence_status
  $st = $es == null ? "unknown" : ($es.comparison == "content" ? $es.state : "unknown")
  $cur = [try]{
    $r = [self:read]{path:$b.path,start_line:$b.source.start_line,end_line:$b.source.end_line,numbered:$b.source.numbered}
    return {read:"ok",excerpt:$r.text,same_as_original:$r.text == $b.excerpt,observation_ref:get($r.data,"source_observation_ref")}
  }[catch]{ return {read:"failed",error:text(error_of($_))} }
  return {id:$b.id,path:$b.path,source:$b.source,excerpt:$b.excerpt,claim:$b.claim,claim_status:"사용자 선언 — 정확성 미검증(판본 변화만 확인)",
    note_id:$b.note_id,note_found:$hit != null,note_locus_matches_path:($hit == null ? false : $hit.locus == $b.path),
    recall_locus_exists:($f == null ? null : get($f,"locus_exists")),
    previous_state:$b.state,state:$st,evidence_status:$es,current_read:$cur}
}
$rows = $base.data.rows >> [table:each]{ [fn:대조]{b:$it} }
return $rows
